export const BOOKING_VISIT_MODES = ["online", "at_client", "at_provider"] as const;
export type BookingVisitMode = (typeof BOOKING_VISIT_MODES)[number];

/** The transitions a member may call (`POST /v1/bookings/{id}/<verb>`); `no_show` is the route `no-show`. */
export const BOOKING_VERBS = ["accept", "decline", "cancel", "start", "complete", "no_show"] as const;
export type BookingVerb = (typeof BOOKING_VERBS)[number];
/** What the caller may do now (SPEC 13d G4): the verbs, plus `review` (client) and `client_review` (provider). */
export const BOOKING_ACTIONS = [...BOOKING_VERBS, "review", "client_review"] as const;
export type BookingAction = (typeof BOOKING_ACTIONS)[number];
export const BOOKING_ACTORS = ["client", "provider", "ops", "system"] as const;

export const BOOKING_RULES = {
  /** a request or proposal not answered within this many hours (or by its start) expires */
  answerWithinHours: 24,
  /** the provider may start the job this many minutes before the start time */
  startEarlyMinutes: 60,
  /** hours a booking lasts (the request's stepper) */
  hours: HOURS,
} as const;

/** When an unanswered request or proposal expires: 24 hours after it was sent, or at its start if that is sooner. */
export function answerDeadline(createdAt: Date, startsAt: Date): Date {
  return new Date(Math.min(createdAt.getTime() + BOOKING_RULES.answerWithinHours * 3_600_000, startsAt.getTime()));
}

export interface TotalInput {
  pricing: Pricing;
  /** the unit price in centavos (per hour, per job, or the per-guest package) */
  unitCentavos: number;
  hours: number;
  guests?: number | null;
  /** per_guest: the guests the unit price includes */
  includedGuests?: number | null;
  /** per_guest: the price of each guest past the included ones */
  extraGuestCentavos?: number | null;
}

/**
 * The total in centavos: per hour, the hours times the rate; per job, the price; per guest, the package plus each
 * guest past the included ones. The same formula api2 stores as `totalCentavos` (SPEC 13c §6.8).
 */
export function estimateTotal(t: TotalInput): number {
  switch (t.pricing) {
    case "per_hour":
      return t.unitCentavos * t.hours;
    case "per_job":
      return t.unitCentavos;
    case "per_guest": {
      const extra = Math.max(0, (t.guests ?? 0) - (t.includedGuests ?? 0));
      return t.unitCentavos + extra * (t.extraGuestCentavos ?? 0);
    }
  }
}

