// ---- typed client ----

type In<S extends z.ZodType> = z.input<S>;
const enc = encodeURIComponent;
const verbPath = (v: BookingVerb) => (v === "no_show" ? "no-show" : v);

export function bookingsApi(api: Client) {
  const one = (id: string) => `/v1/bookings/${enc(id)}`;
  return {
    /** `idempotencyKey`: created when the booking screen opens, reused for every retry of the same body */
    create: (body: In<typeof createBookingBodySchema>, idempotencyKey: string): Promise<ApiResult<Booking>> => api.post("/v1/bookings", body, { idempotencyKey, schema: bookingSchema }),
    list: (q: { status?: readonly BookingStatus[]; cursor?: string | null; limit?: number; order?: "asc" | "desc" } = {}): Promise<ApiResult<BookingList>> =>
      api.get("/v1/bookings", { query: { status: q.status?.join(","), cursor: q.cursor, limit: q.limit, order: q.order }, schema: bookingListSchema }),
    picker: (q: { status?: readonly BookingStatus[]; cursor?: string | null } = {}): Promise<ApiResult<BookingPickerList>> =>
      api.get("/v1/bookings", { query: { status: q.status?.join(","), cursor: q.cursor, fields: "picker" }, schema: bookingPickerListSchema }),
    get: (id: string): Promise<ApiResult<Booking>> => api.get(one(id), { schema: bookingSchema }),
    transition: (id: string, verb: BookingVerb, body?: In<typeof bookingTransitionBodySchema>): Promise<ApiResult<Booking>> => api.post(`${one(id)}/${verbPath(verb)}`, body ?? {}, { schema: bookingSchema }),
    /** the `.ics` path (web: a download link; app: download, then the share sheet) */
    calendarPath: (id: string): string => `${one(id)}/calendar.ics`,
  };
}

export function opsBookingsApi(api: Client) {
  const one = (id: string) => `/v1/ops/bookings/${enc(id)}`;
  return {
    list: (q: In<typeof opsBookingsQuerySchema> & { status?: string } = {}): Promise<ApiResult<OpsBookingPage>> => api.get("/v1/ops/bookings", { query: q as Record<string, string | number | undefined>, schema: opsBookingPageSchema }),
    get: (id: string): Promise<ApiResult<OpsBookingDetail>> => api.get(one(id), { schema: opsBookingDetailSchema }),
    cancel: (id: string, body: In<typeof opsReasonBodySchema>): Promise<ApiResult<OpsBookingDetail>> => api.post(`${one(id)}/cancel`, body, { schema: opsBookingDetailSchema }),
  };
}
